import assert from 'node:assert/strict';
import fs from 'node:fs';
import {createHash} from 'node:crypto';
import * as T from '@nautilus-engine/renderer/render-effects/three';
import {createFarmyardDoorPresentation,farmyardDoorVisualResourceURLs,FARMYARD_DOOR_VISUAL_SOURCE as source} from '@nautilus-engine/renderer/adapters/farmyard/doors/three';
const base=new URL('node_modules/@nautilus-engine/renderer/',import.meta.url);
const provenance=JSON.parse(fs.readFileSync(new URL('package-provenance.json',base)));
const urls=farmyardDoorVisualResourceURLs();assert.deepEqual(Object.keys(urls),['wood']);
assert.ok(urls.wood.startsWith(base.href));const raw=fs.readFileSync(new URL(urls.wood));
assert.equal(raw.length,source.wood.bytes);assert.equal(createHash('sha256').update(raw).digest('hex'),source.wood.sha256);
assert.equal(raw.subarray(0,8).toString('hex'),'89504e470d0a1a0a');
const row=provenance.files.find(row=>new URL(row.path,base).href===urls.wood);assert.ok(row);assert.equal(row.sha256,source.wood.sha256);
assert.equal(fs.existsSync(new URL('vendor/farmyard-door-visuals/'+source.commit+'/'+source.reference,base)),false);
const collider={id:'door:installed',interactionId:'door:installed',kind:'wall',x0:1.44,x1:2.56,y0:1.92,y1:2.08,z0:0,height:2};
const texture=new T.Texture();let borrowedDisposals=0;texture.addEventListener('dispose',()=>borrowedDisposals++);
const visual=await createFarmyardDoorPresentation({collider,known:true,visible:true,texture});
assert.ok(visual.root instanceof T.Group);assert.ok(visual.leaf instanceof T.Mesh);
assert.notEqual(visual.leaf.material.map,texture);assert.equal(visual.leaf.material.map.colorSpace,T.SRGBColorSpace);
assert.equal(visual.leaf.material.color.getHex(),source.material.color);assert.equal(visual.leaf.material.roughness,.9);
assert.equal(visual.leaf.castShadow,true);assert.equal(visual.leaf.receiveShadow,true);
const bounds=new T.Box3().setFromObject(visual.root);assert.ok(Math.abs(bounds.min.x-collider.x0)<1e-7);assert.ok(Math.abs(bounds.max.z-collider.y1)<1e-7);assert.equal(bounds.max.y,2);
assert.equal(visual.update({collider,known:true,visible:true}),false);
const open={...collider,x0:2,x1:2.16,y0:1.44,y1:2.56};visual.update({collider:open,known:true,visible:false});
assert.equal(visual.leaf.visible,true);assert.equal(visual.leaf.material.color.getHex(),source.material.color);
const before=visual.diagnostics();assert.throws(()=>visual.update({collider:{...open,height:3},known:true,visible:true}));assert.deepEqual(visual.diagnostics(),before);
visual.update({collider:open,known:false,visible:false});assert.equal(visual.leaf.visible,false);
const scene=new T.Scene();scene.add(visual.root);visual.dispose();visual.dispose();assert.equal(scene.children.length,0);assert.equal(borrowedDisposals,0);assert.equal(visual.diagnostics().disposed,true);
assert.throws(()=>visual.update({collider,known:true,visible:true}));texture.dispose();assert.equal(borrowedDisposals,1);
console.log('Installed optional door renderer: exact original paint, shared Three, native current-collider bounds, remembered visibility and borrowed-resource retirement pass.');
